NAME = 'GerLeoNA28: Leonberger Bibel, NT (NA28)'
BOOK = 'Colossians'

CHAPTERS = {
    1: {
        1: 'Paulus, ein Apostel von Christus Jesus durch den Willen Gottes, und Bruder Timotheus. /',
        2: 'An die in Kolossä [lebenden] heiligen und gläubigen Geschwister in Christus: /Gnade [sei mit] euch und Friede von Gott, unserem Vater!',
        3: 'Wir danken Gott, dem Vater unseres Herrn Jesus Christus, indem wir ständig für euch beten,',
        4: 'weil wir von eurem Glauben in Christus Jesus gehört haben und von der Liebe, die ihr zu allen Heiligen habt,',
        5: 'um der Hoffnung willen, die in den Himmeln für euch aufbewahrt wird [und] von der ihr vorab gehört habt durch das Wort der Wahrheit aus der guten Nachricht,',
        6: 'die zu euch gelangt ist, wie sie auch in aller Welt Früchte trägt und sich ausbreitet, wie auch unter euch seit dem Tag, als ihr sie gehört habt und die Gnade Gottes in Wahrheit erkannt habt;',
        7: 'wie ihr von Epaphras, unserem geliebten Mitknecht, gelernt habt, der [im Auftrag] für euch ein treuer Diener des Christus ist',
        8: '[und] der uns auch auf eure Liebe im Geist hingewiesen hat.',
        9: 'Deshalb hören auch wir nicht auf – seit dem Tag, als wir davon hörten –, für euch zu beten und zu bitten, dass ihr erfüllt werdet mit der Erkenntnis seines Willens in aller Weisheit und geistlichem Verständnis,',
        10: 'um in einer Weise zu leben, die des Herrn würdig [ist], zu allem Wohlgefallen: indem ihr mit allem guten Werk Frucht bringt und in der Erkenntnis Gottes wachst;',
        11: 'indem ihr mit aller Kraft gemäß seiner herrlichen Macht befähigt werdet zu aller Geduld und Ausdauer. Mit Freude',
        12: 'dankt dem Vater, der euch ermächtigt hat zur Teilhabe an dem Erbe der Heiligen im Licht!',
        13: 'Er hat uns aus dem Einflussbereich der Finsternis gerettet und in das Reich des seines geliebten Sohnes versetzt.',
        14: 'In ihm haben wir die Erlösung, die Vergebung der Sünden.',
        15: 'Er ist das Ebenbild des unsichtbaren Gottes, der Erstgeborene aller Schöpfung,',
        16: 'weil in ihm alles geschaffen worden ist, in den Himmeln und auf der Erde, was sichtbar und was unsichtbar [ist] – seien es Throne oder Herrscher, seien es Urgewalten oder Mächte: Alles ist durch ihn und auf ihn hin geschaffen!',
        17: 'Und er ist vor allem, und alles besteht in ihm.',
        18: 'Und er ist das Haupt des Leibes, [also] der Gemeinde. Er ist der Anfang, der Erstgeborene von den Toten, sodass er in allem Vorreiter geworden ist,',
        19: 'weil er Gefallen daran hatte, in ihm die ganze Fülle wohnen zu lassen',
        20: 'und durch ihn alles mit sich zu versöhnen, indem er Frieden gestiftet hat durch das Blut seines Kreuzes – durch ihn [ist alles versöhnt], ob auf der Erde oder in den Himmeln.',
        21: 'Auch euch, die ihr früher Fremde und Feinde wart durch [eure] Beschäftigung mit den bösen Werken,',
        22: 'hat er jetzt aber versöhnt in seinem Körper aus Fleisch durch den Tod, um euch heilig und unbefleckt und unbescholten vor ihm zu präsentieren,',
        23: 'sofern ihr im Glauben gegründet und fest bleibt und nicht abrückt von der Hoffnung der guten Nachricht, die ihr gehört habt [und] die durch alle Schöpfung unter dem Himmel gepredigt wurde [und] deren Diener ich, Paulus, geworden bin.',
        24: 'Jetzt freue ich mich in den Leiden für euch und ergänze durch meinen Körper, was noch fehlt von den Bedrängnissen des Christus für seinen Leib, der die Gemeinde ist.',
        25: 'Ihr Diener bin ich geworden entsprechend der Verwaltung Gottes, die mir euch gegenüber gegeben wurde, um das Wort Gottes auszufüllen,',
        26: 'das Geheimnis, das vor den Zeitaltern und vor den Generationen verborgen war, jetzt aber seinen Heiligen offenbar geworden ist.',
        27: 'Ihnen wollte Gott bekannt machen, was der herrliche Reichtum dieses Geheimnisses unter den Heiden [ist], das heißt: Christus in euch, die Hoffnung der Herrlichkeit.',
        28: 'Ihn verkünden wir, indem wir jeden Menschen ermahnen und jeden Menschen in aller Weisheit lehren, damit wir jeden Menschen als in Christus vollkommen präsentieren.',
        29: 'Darauf arbeite ich auch hin, während ich entsprechend seinem Wirken ringe, das in mir mit Kraft wirkt.',
    },
    2: {
        1: 'Ich will nämlich, dass ihr wisst, welch große Anstrengung ich unternehme für euch und die [Geschwister] in Laodizea und alle, die mein Angesicht nicht persönlich gesehen haben,',
        2: 'damit ihre Herzen ermutigt werden, vereint in Liebe und zu allem Reichtum an Gewissheit der Einsicht, zur Erkenntnis des Geheimnisses Gottes, des Christus,',
        3: 'in dem alle Schätze der Weisheit und der Erkenntnis verborgen sind.',
        4: 'Dies sage ich, damit euch niemand mit [seiner] Überredungskunst täuscht.',
        5: 'Denn wenn ich auch körperlich abwesend bin, bin ich doch im Geist bei euch, sodass ich mich freue und eure Ordnung und die Festigkeit eures Glaubens an Christus sehe.',
        6: 'Wie ihr nun Christus Jesus als den Herrn angenommen habt, so lebt in ihm,',
        7: 'verwurzelt und auferbaut in ihm und gefestigt im Glauben, wie ihr gelehrt worden seid, überfließend mit Danksagung!',
        8: 'Seht zu, dass es niemanden gibt, der euch durch die Philosophie und leeren Betrug einfängt, gemäß der Tradition der Menschen, gemäß der Elemente der Welt und nicht gemäß Christus.',
        9: 'Denn in ihm wohnt leibhaftig die ganze Fülle der Gottheit,',
        10: 'und ihr seid in ihm erfüllt, der der Ausgangspunkt jeder Urgewalt und Macht ist.',
        11: 'In ihm seid ihr auch mit einer Beschneidung beschnitten worden, die nicht mit Händen vollzogen [ist], sondern durch das Ausziehen des fleischlichen Körpers in der Beschneidung Christi.',
        12: 'Da ihr in der Taufe zusammen mit ihm begraben wurdet, wurdet ihr darin auch zusammen mit ihm auferweckt durch den Glauben an das Wirken Gottes, der ihn von den Toten auferweckt hat.',
        13: 'Und euch, die ihr tot wart in den Übertretungen und der Unbeschnittenheit eures Fleisches … euch hat er zusammen mit ihm lebendig gemacht, indem er uns alle Übertretungen verziehen hat.',
        14: 'Er hat unseren Schuldschein getilgt, der durch die Satzungen gegen uns war; und er hat ihn aus dem Weg geräumt, indem er ihn ans Kreuz genagelt hat.',
        15: 'Er hat die Urgewalten und Mächte entwaffnet und öffentlich zur Schau gestellt, sodass er dadurch über sie triumphiert hat.',
        16: 'Deshalb soll niemand euch beurteilen im Essen und im Trinken oder in Bezug auf ein Fest oder einen Neumond oder einen Sabbat,',
        17: 'die ein Schatten der zukünftigen [Dinge] sind, der Körper aber [ist] der von Christus.',
        18: 'Es soll euch niemand disqualifizieren, der auf Demut und Anbetung der Engel besteht und [auf Dinge] Wert legt, die er gesehen hat, grundlos aufgeblasen durch seine ‹fleischliche Gesinnung›,',
        19: 'und nicht das Haupt festhält, von dem aus der ganze Leib, unterstützt und zusammengefügt durch die Gelenke und Bänder, das Wachstum Gottes wächst.',
        20: 'Wenn ihr zusammen mit Christus den Elementen der Welt gestorben seid, warum unterwerft ihr euch ihnen, als ob ihr in der Welt lebt?',
        21: '„Berühre nicht und koste nicht und betaste nicht!“,',
        22: 'was alles zur Vernichtung durch Abnutzung [bestimmt] ist – gemäß den Geboten und Lehren der Menschen?',
        23: 'Sie haben zwar den Anschein von Weisheit, in eigenwilliger Religion und Erniedrigung und Kasteiung des Körpers, [aber] sie sind wertlos gegen die Befriedigung des Fleisches.',
    },
    3: {
        1: 'Wenn ihr also mit Christus auferweckt worden seid, dann sucht das, was oben [ist], wo Christus zur Rechten Gottes sitzt.',
        2: 'Besinnt euch auf das, was oben [ist], nicht auf das, was auf der Erde [ist]!',
        3: 'Ihr seid nämlich gestorben, und euer Leben ist zusammen mit Christus in Gott verborgen.',
        4: 'Sobald Christus – euer Leben – erscheint, dann werdet auch ihr zusammen mit ihm in Herrlichkeit erscheinen.',
        5: 'Tötet also die Glieder, die auf der Erde [sind]: Unzucht, Unreinheit, Lust, boshafte Begierde, und die Habgier, welche Götzendienst ist.',
        6: 'Derentwegen kommt der Zorn Gottes über die Söhne des Ungehorsams,',
        7: 'unter denen auch ihr früher gewandelt seid, als ihr darin gelebt habt.',
        8: 'Jetzt aber sollt auch ihr das alles ablegen: Zorn, Wut, Bosheit, Lästerei, obszönes Gerede aus eurem Mund.',
        9: 'Belügt einander nicht, da ihr den alten Menschen samt seinen Taten ausgezogen',
        10: 'und den neuen angezogen habt, der erneuert wird zur Erkenntnis nach dem Bild dessen, der ihn geschaffen hat,',
        11: 'wo es weder Grieche noch Judäer gibt, Beschneidung und Unbeschnittenheit, Barbar, Skythe, Sklave, freier [Bürger], sondern alles und in allem [ist] Christus.',
        12: 'Zieht nun als Erwählte Gottes, als Heilige und Geliebte, ‹herzliches Erbarmen›, Güte, Demut, Sanftmut, Langmut an,',
        13: 'sodass ihr einander ertragt und euch gegenseitig verzeiht, wenn jemand eine Beschwerde gegen jemanden hat. Wie der Herr euch verziehen hat, so auch ihr!',
        14: 'Aber über all diese [Dinge] hinaus [zieht an] die Liebe, das heißt: das Band der Vollkommenheit.',
        15: 'Und der Friede Christi, zu dem ihr auch in einem Leib berufen worden seid, regiere in euren Herzen. Und seid dankbar!',
        16: 'Das Wort Christi soll reichlich unter euch wohnen, indem ihr euch gegenseitig in aller Weisheit mit Psalmen, Hymnen, geistlichen Liedern lehrt und ermahnt [und] indem ihr mit Dankbarkeit in euren Herzen zu Gott singt.',
        17: 'Und alles, was ihr tut, in Wort oder in Werk … [tut] alles im Namen des Herrn Jesus und dankt Gott dem Vater durch ihn!',
        18: 'Ihr Frauen, ordnet euch [euren] Ehemännern unter, wie es sich im Herrn gehört.',
        19: 'Ihr Männer, liebt [eure] Ehefrauen und seid ihnen gegenüber nicht verbittert.',
        20: 'Ihr Kinder, gehorcht [euren] Eltern in allem, denn das im Herrn ‹Gefallen findet›.',
        21: 'Ihr Väter, provoziert eure Kinder nicht, damit sie nicht entmutigt werden.',
        22: 'Ihr Sklaven, gehorcht in jeder [Hinsicht] den irdischen Herren, nicht mit Augenwischerei, als Ja-Sager, sondern mit der Aufrichtigkeit des Herzens, indem ihr den Herrn fürchtet.',
        23: 'Was auch immer ihr macht, das tut von Herzen, als ob [es] für den Herrn und nicht für Menschen [wäre],',
        24: 'weil ihr wisst, dass ihr vom Herrn die Belohnung des Erbes empfangen werdet. Dient dem Herrn Christus!',
        25: 'Wer nämlich Unrecht tut, wird bekommen, was er Unrechtes getan hat, und [in dieser Frage] gibt es keine Parteilichkeit.',
    },
    4: {
        1: 'Ihr Herren, gewährt den Sklaven, was recht [ist], und den [nötigen] Ausgleich, da ihr wisst, dass auch ihr einen Herrn im Himmel habt.',
        2: 'Am Gebet haltet fest, wacht darin mit Danksagung,',
        3: 'betet zugleich auch für uns, dass Gott uns eine Tür öffnet für das Wort, von dem Geheimnis des Christus zu reden, weswegen ich auch gefangen bin,',
        4: 'dass ich es offenbare, wie ich reden muss.',
        5: 'Führt euer Leben mit Weisheit gegenüber denen außerhalb [der Gemeinde], sodass ihr die Zeit ausnützt.',
        6: 'Euer Wort [geschehe] stets in Gnade, mit Salz gewürzt, um zu wissen, wie ihr einem jedem antworten müsst.',
        7: '‹Was mich angeht›, wird euch Tychikus alles wissen lassen – der geliebte Bruder und treue Diener und Mitknecht im Herrn,',
        8: 'den ich aus eben diesem [Grund] zu euch geschickt habe, damit ihr ‹unsere Umstände› erfahrt und er eure Herzen ermutigt,',
        9: 'zusammen mit dem treuen und geliebten Bruder Onesimus, der [einer] von euch ist. Sie werden euch alles wissen lassen, was hier [passiert].',
        10: 'Es grüßen euch Aristarchus, mein Mitgefangener, und Markus, der Vetter von Barnabas, über den ihr Anweisungen erhalten habt – falls er zu euch kommen sollte, empfangt ihn! –,',
        11: 'und Jesus, der [mit Beinamen] Justus genannt wird. Sie sind aus der Beschneidung; sie allein [sind] Mitarbeiter am Reich Gottes, welche mir ein Trost geworden sind.',
        12: 'Es grüßt euch Epaphras, der [einer] von euch [ist], ein Knecht von Christus Jesus, der ständig in den Gebeten für euch ringt, damit ihr fest steht, reif und völlig überzeugt in jedem Willen Gottes.',
        13: 'Denn ich bescheinige ihm, dass er viel Mühe um euch und diejenigen in Laodizea und diejenigen in Hierapolis hat.',
        14: 'Es grüßt euch Lukas, der Arzt, der geliebte [Freund], und auch Demas.',
        15: 'Grüßt die Geschwister in Laodizea und Nympha samt der Gemeinde in ihrem Haus!',
        16: 'Und sobald ihr den Brief bei euch vorgelesen habt, sorgt dafür, dass er auch in der Gemeinde der Laodizeer vorgelesen wird, und den von Laodizea, dass auch ihr ihn vorlest.',
        17: 'Und sagt Archippus: „Versieh den Dienst, den du im Herrn empfangen hast, damit du ihn erfüllst!“',
        18: 'Der Gruß [stammt] aus meiner Hand, von Paulus. Denkt an meine Gefangenschaft! Die Gnade [sei] mit euch!',
    },
}
